solution:
fn safe_multiply(a: Int, b: Int) -> Option[Int] {
  return a.checked_mul(b);
}

fn main() -> Int {
  let result = safe_multiply(1000000, 1000000);
  return match result {
    Some(_) => 1,
    None => 0,
  };
}
